insert into public.exercises(id,team_id,document) values
('wall-angels', null, '{"id":"wall-angels","slug":"wall-angels","name":"Wall Angels","categories":["mobilita"],"muscleGroups":["Spalle","Scapole"],"difficulty":"beginner","description":"Porta le braccia a W e falle scorrere lentamente verso l’alto. Fermati prima di inarcare la schiena e torna alla W.","objective":"Allenare spalle,scapole con un movimento controllato.","swimmingBenefits":["Favorisce il movimento controllato di spalle, torace, anche e caviglie per una posizione più allineata in acqua."],"instructions":["Appoggia schiena e bacino alla parete, piedi poco avanti.","Porta le braccia a W e falle scorrere lentamente verso l’alto.","Fermati prima di inarcare la schiena e torna alla W."],"commonMistakes":["Sollevare le costole o forzare i polsi contro il muro."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Riduci l’altezza delle braccia.","harderVariation":"Aggiungi una pausa di due secondi in alto.","defaultSets":2,"dose":{"mode":"reps","reps":10,"sides":1,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Parete"],"youtubeSearchQuery":"Wall Angels esercizio tecnica","custom":false}'::jsonb),
('thread-the-needle', null, '{"id":"thread-the-needle","slug":"thread-the-needle","name":"Thread the Needle","categories":["mobilita"],"muscleGroups":["Torace","Spalle"],"difficulty":"beginner","description":"Fai passare un braccio sotto l’altro ruotando il torace. Riapri lentamente e ripeti sull’altro lato senza spostare il bacino.","objective":"Allenare torace,spalle con un movimento controllato.","swimmingBenefits":["Favorisce il movimento controllato di spalle, torace, anche e caviglie per una posizione più allineata in acqua."],"instructions":["Mettiti a quattro appoggi, mani sotto le spalle.","Fai passare un braccio sotto l’altro ruotando il torace.","Riapri lentamente e ripeti sull’altro lato senza spostare il bacino."],"commonMistakes":["Ruotare solo il collo o crollare sulla spalla."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Esegui una rotazione più piccola.","harderVariation":"Apri il gomito verso il soffitto nella risalita.","defaultSets":2,"dose":{"mode":"reps","reps":8,"sides":2,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Thread the Needle esercizio tecnica","custom":false}'::jsonb),
('worlds-greatest-stretch', null, '{"id":"worlds-greatest-stretch","slug":"worlds-greatest-stretch","name":"World’s Greatest Stretch","categories":["mobilita"],"muscleGroups":["Anche","Torace"],"difficulty":"intermediate","description":"Appoggia il ginocchio posteriore se serve e ruota il torace aprendo un braccio. Riporta la mano a terra, cambia lato e muoviti senza rimbalzi.","objective":"Allenare anche,torace con un movimento controllato.","swimmingBenefits":["Favorisce il movimento controllato di spalle, torace, anche e caviglie per una posizione più allineata in acqua."],"instructions":["Da un affondo lungo appoggia le mani dentro il piede anteriore.","Appoggia il ginocchio posteriore se serve e ruota il torace aprendo un braccio.","Riporta la mano a terra, cambia lato e muoviti senza rimbalzi."],"commonMistakes":["Forzare il gomito a terra o perdere l’equilibrio."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Appoggia sempre il ginocchio posteriore.","harderVariation":"Tieni la gamba posteriore distesa.","defaultSets":1,"dose":{"mode":"reps","reps":5,"sides":2,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"World’s Greatest Stretch esercizio tecnica","custom":false}'::jsonb),
('hip-switch', null, '{"id":"hip-switch","slug":"hip-switch","name":"90/90 Hip Switch","categories":["mobilita"],"muscleGroups":["Anche","Glutei"],"difficulty":"beginner","description":"Ruota le ginocchia da un lato all’altro mantenendo il controllo. Accompagna il movimento del bacino e conta ogni cambio.","objective":"Allenare anche,glutei con un movimento controllato.","swimmingBenefits":["Favorisce il movimento controllato di spalle, torace, anche e caviglie per una posizione più allineata in acqua."],"instructions":["Siediti con entrambe le ginocchia piegate a circa 90 gradi.","Ruota le ginocchia da un lato all’altro mantenendo il controllo.","Accompagna il movimento del bacino e conta ogni cambio."],"commonMistakes":["Spingere sulle ginocchia o forzare l’anca."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Appoggia le mani dietro il bacino.","harderVariation":"Tieni le mani davanti al petto.","defaultSets":2,"dose":{"mode":"reps","reps":10,"sides":1,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"90/90 Hip Switch esercizio tecnica","custom":false}'::jsonb),
('cat-cow', null, '{"id":"cat-cow","slug":"cat-cow","name":"Cat-Cow","categories":["mobilita"],"muscleGroups":["Colonna","Addominali"],"difficulty":"beginner","description":"Espira arrotondando dolcemente la schiena. Inspira distendendo la colonna senza comprimere il collo.","objective":"Allenare colonna,addominali con un movimento controllato.","swimmingBenefits":["Favorisce il movimento controllato di spalle, torace, anche e caviglie per una posizione più allineata in acqua."],"instructions":["Mettiti a quattro appoggi con ginocchia sotto le anche.","Espira arrotondando dolcemente la schiena.","Inspira distendendo la colonna senza comprimere il collo."],"commonMistakes":["Iperestendere il tratto lombare o muoversi a scatti."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Riduci l’ampiezza del movimento.","harderVariation":"Allunga espirazione e controllo senza aumentare l’arco.","defaultSets":1,"dose":{"mode":"reps","reps":12,"sides":1,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Cat-Cow esercizio tecnica","custom":false}'::jsonb),
('shoulder-circles', null, '{"id":"shoulder-circles","slug":"shoulder-circles","name":"Circonduzioni delle spalle","categories":["mobilita"],"muscleGroups":["Spalle"],"difficulty":"beginner","description":"Esegui cerchi controllati delle spalle, senza ruotare il tronco. Completa 15 cerchi avanti e 15 indietro: i due passaggi indicano le direzioni.","objective":"Allenare spalle con un movimento controllato.","swimmingBenefits":["Favorisce il movimento controllato di spalle, torace, anche e caviglie per una posizione più allineata in acqua."],"instructions":["Stai in piedi con braccia rilassate e ginocchia morbide.","Esegui cerchi controllati delle spalle, senza ruotare il tronco.","Completa 15 cerchi avanti e 15 indietro: i due passaggi indicano le direzioni."],"commonMistakes":["Alzare le spalle con tensione o accelerare troppo."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Disegna cerchi più piccoli.","harderVariation":"Aumenta gradualmente l’ampiezza indolore.","defaultSets":1,"dose":{"mode":"reps","reps":15,"sides":2,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Circonduzioni delle spalle esercizio tecnica","custom":false}'::jsonb),
('knee-to-wall', null, '{"id":"knee-to-wall","slug":"knee-to-wall","name":"Knee to Wall","categories":["mobilita"],"muscleGroups":["Caviglie","Polpacci"],"difficulty":"beginner","description":"Avvicina il ginocchio alla parete mantenendo il tallone a terra. Segui la direzione del secondo dito e torna indietro.","objective":"Allenare caviglie,polpacci con un movimento controllato.","swimmingBenefits":["Favorisce il movimento controllato di spalle, torace, anche e caviglie per una posizione più allineata in acqua."],"instructions":["Metti un piede davanti a una parete a pochi centimetri.","Avvicina il ginocchio alla parete mantenendo il tallone a terra.","Segui la direzione del secondo dito e torna indietro."],"commonMistakes":["Sollevare il tallone o far cadere il ginocchio all’interno."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Avvicina il piede alla parete.","harderVariation":"Allontana di poco il piede mantenendo il controllo.","defaultSets":1,"dose":{"mode":"reps","reps":10,"sides":2,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Parete"],"youtubeSearchQuery":"Knee to Wall esercizio tecnica","custom":false}'::jsonb),
('deep-squat', null, '{"id":"deep-squat","slug":"deep-squat","name":"Deep Squat Hold dinamico","categories":["mobilita"],"muscleGroups":["Anche","Caviglie"],"difficulty":"beginner","description":"Sposta lentamente il peso tra i lati mantenendo i talloni appoggiati. Respira e risali con controllo, senza cercare profondità forzate.","objective":"Allenare anche,caviglie con un movimento controllato.","swimmingBenefits":["Favorisce il movimento controllato di spalle, torace, anche e caviglie per una posizione più allineata in acqua."],"instructions":["Apri i piedi poco oltre le anche e scendi nell’accosciata confortevole.","Sposta lentamente il peso tra i lati mantenendo i talloni appoggiati.","Respira e risali con controllo, senza cercare profondità forzate."],"commonMistakes":["Arrotondare molto la schiena o forzare le ginocchia."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Usa una profondità ridotta con le mani su una parete.","harderVariation":"Aggiungi una piccola apertura toracica alternata.","defaultSets":1,"dose":{"mode":"time","durationSeconds":25,"sides":1,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Deep Squat Hold dinamico esercizio tecnica","custom":false}'::jsonb),
('scapular-push-up', null, '{"id":"scapular-push-up","slug":"scapular-push-up","name":"Scapular Push-up","categories":["mobilita","parte-superiore"],"muscleGroups":["Scapole","Spalle"],"difficulty":"intermediate","description":"Avvicina delicatamente le scapole senza piegare i gomiti. Spingi il pavimento allontanando le scapole senza incurvare la zona lombare.","objective":"Allenare scapole,spalle con un movimento controllato.","swimmingBenefits":["Favorisce il movimento controllato di spalle, torace, anche e caviglie per una posizione più allineata in acqua.","Rinforza i muscoli di spinta e gli stabilizzatori scapolari per sostenere il controllo delle spalle in acqua."],"instructions":["Assumi un plank con braccia tese e corpo allineato.","Avvicina delicatamente le scapole senza piegare i gomiti.","Spingi il pavimento allontanando le scapole senza incurvare la zona lombare."],"commonMistakes":["Piegare i gomiti o lasciar cedere il bacino."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Esegui a quattro appoggi o alla parete.","harderVariation":"Fai una breve pausa nella spinta finale.","defaultSets":2,"dose":{"mode":"reps","reps":12,"sides":1,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Scapular Push-up esercizio tecnica","custom":false}'::jsonb),
('hip-flexor-stretch', null, '{"id":"hip-flexor-stretch","slug":"hip-flexor-stretch","name":"Stretch dei flessori dell’anca","categories":["flessibilita"],"muscleGroups":["Anche","Quadricipiti"],"difficulty":"beginner","description":"Contrai leggermente il gluteo posteriore e porta il bacino poco avanti. Mantieni il busto alto e respira, poi cambia lato.","objective":"Mantenere una tensione muscolare lieve e confortevole.","swimmingBenefits":["Aiuta a mantenere l’ampiezza di movimento necessaria alla nuotata e a ritrovare una sensazione di rilassamento."],"instructions":["In mezzo inginocchio, metti un piede avanti e proteggi il ginocchio con un asciugamano.","Contrai leggermente il gluteo posteriore e porta il bacino poco avanti.","Mantieni il busto alto e respira, poi cambia lato."],"commonMistakes":["Inarcare la zona lombare per aumentare la tensione."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata.","Cerca solo una tensione lieve: niente rimbalzi, spinte esterne o stretching doloroso."],"prerequisites":[],"easierVariation":"Sposta meno il bacino.","harderVariation":"Solleva il braccio del lato in appoggio senza inarcarti.","defaultSets":1,"dose":{"mode":"time","durationSeconds":25,"sides":2,"positions":1,"secondsPerRep":3},"restSeconds":10,"equipment":["Corpo libero"],"youtubeSearchQuery":"Stretch dei flessori dell’anca esercizio tecnica","custom":false}'::jsonb),
('door-pec-stretch', null, '{"id":"door-pec-stretch","slug":"door-pec-stretch","name":"Stretch dei pettorali alla porta","categories":["flessibilita"],"muscleGroups":["Pettorali","Spalle"],"difficulty":"beginner","description":"Fai un piccolo passo avanti finché senti una tensione lieve nel petto. Respira e torna indietro lentamente prima di cambiare lato.","objective":"Mantenere una tensione muscolare lieve e confortevole.","swimmingBenefits":["Aiuta a mantenere l’ampiezza di movimento necessaria alla nuotata e a ritrovare una sensazione di rilassamento."],"instructions":["Appoggia avambraccio e mano su uno stipite stabile, gomito sotto l’altezza della spalla.","Fai un piccolo passo avanti finché senti una tensione lieve nel petto.","Respira e torna indietro lentamente prima di cambiare lato."],"commonMistakes":["Portare il gomito troppo alto o spingere sull’articolazione."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata.","Cerca solo una tensione lieve: niente rimbalzi, spinte esterne o stretching doloroso."],"prerequisites":[],"easierVariation":"Tieni il gomito più basso e riduci il passo.","harderVariation":"Aumenta di poco la rotazione del tronco, solo senza dolore.","defaultSets":1,"dose":{"mode":"time","durationSeconds":25,"sides":2,"positions":1,"secondsPerRep":3},"restSeconds":10,"equipment":["Stipite"],"youtubeSearchQuery":"Stretch dei pettorali alla porta esercizio tecnica","custom":false}'::jsonb),
('hamstring-stretch', null, '{"id":"hamstring-stretch","slug":"hamstring-stretch","name":"Stretch degli ischiocrurali","categories":["flessibilita"],"muscleGroups":["Ischiocrurali"],"difficulty":"beginner","description":"Inclina il busto dalle anche mantenendo la schiena lunga. Fermati a una tensione leggera dietro la coscia e cambia lato.","objective":"Mantenere una tensione muscolare lieve e confortevole.","swimmingBenefits":["Aiuta a mantenere l’ampiezza di movimento necessaria alla nuotata e a ritrovare una sensazione di rilassamento."],"instructions":["Siediti con una gamba distesa e l’altra piegata comodamente.","Inclina il busto dalle anche mantenendo la schiena lunga.","Fermati a una tensione leggera dietro la coscia e cambia lato."],"commonMistakes":["Curvare il dorso per raggiungere il piede o bloccare il ginocchio."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata.","Cerca solo una tensione lieve: niente rimbalzi, spinte esterne o stretching doloroso."],"prerequisites":[],"easierVariation":"Piega leggermente la gamba distesa.","harderVariation":"Inclina di poco di più il bacino mantenendo la colonna lunga.","defaultSets":1,"dose":{"mode":"time","durationSeconds":25,"sides":2,"positions":1,"secondsPerRep":3},"restSeconds":10,"equipment":["Corpo libero"],"youtubeSearchQuery":"Stretch degli ischiocrurali esercizio tecnica","custom":false}'::jsonb),
('child-pose', null, '{"id":"child-pose","slug":"child-pose","name":"Stretch dei dorsali in Child’s Pose","categories":["flessibilita"],"muscleGroups":["Dorsali","Spalle"],"difficulty":"beginner","description":"Cammina con le mani leggermente verso un lato per allungare il fianco opposto. Respira nel fianco e cambia direzione con lentezza.","objective":"Mantenere una tensione muscolare lieve e confortevole.","swimmingBenefits":["Aiuta a mantenere l’ampiezza di movimento necessaria alla nuotata e a ritrovare una sensazione di rilassamento."],"instructions":["Da quattro appoggi porta il bacino verso i talloni senza forzare le ginocchia.","Cammina con le mani leggermente verso un lato per allungare il fianco opposto.","Respira nel fianco e cambia direzione con lentezza."],"commonMistakes":["Premere sul collo o insistere se le ginocchia fanno male."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata.","Cerca solo una tensione lieve: niente rimbalzi, spinte esterne o stretching doloroso."],"prerequisites":[],"easierVariation":"Mantieni il bacino più alto o appoggia le mani alla parete.","harderVariation":"Allunga poco di più le dita mantenendo le spalle rilassate.","defaultSets":1,"dose":{"mode":"time","durationSeconds":25,"sides":2,"positions":1,"secondsPerRep":3},"restSeconds":10,"equipment":["Corpo libero"],"youtubeSearchQuery":"Stretch dei dorsali in Child’s Pose esercizio tecnica","custom":false}'::jsonb),
('calf-stretch', null, '{"id":"calf-stretch","slug":"calf-stretch","name":"Stretch del polpaccio contro la parete","categories":["flessibilita"],"muscleGroups":["Polpacci","Caviglie"],"difficulty":"beginner","description":"Tieni il tallone posteriore a terra e il piede diretto avanti. Inclina il corpo verso la parete e cambia lato senza rimbalzare.","objective":"Mantenere una tensione muscolare lieve e confortevole.","swimmingBenefits":["Aiuta a mantenere l’ampiezza di movimento necessaria alla nuotata e a ritrovare una sensazione di rilassamento."],"instructions":["Appoggia le mani alla parete e porta una gamba indietro.","Tieni il tallone posteriore a terra e il piede diretto avanti.","Inclina il corpo verso la parete e cambia lato senza rimbalzare."],"commonMistakes":["Ruotare il piede all’esterno o sollevare il tallone."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata.","Cerca solo una tensione lieve: niente rimbalzi, spinte esterne o stretching doloroso."],"prerequisites":[],"easierVariation":"Riduci la distanza tra i piedi.","harderVariation":"Aumenta poco la distanza conservando il tallone a terra.","defaultSets":1,"dose":{"mode":"time","durationSeconds":25,"sides":2,"positions":1,"secondsPerRep":3},"restSeconds":10,"equipment":["Parete"],"youtubeSearchQuery":"Stretch del polpaccio contro la parete esercizio tecnica","custom":false}'::jsonb),
('quad-stretch', null, '{"id":"quad-stretch","slug":"quad-stretch","name":"Stretch dei quadricipiti in piedi","categories":["flessibilita"],"muscleGroups":["Quadricipiti"],"difficulty":"beginner","description":"Avvicina le ginocchia mantenendo il bacino neutro. Respira senza tirare il piede e passa all’altro lato.","objective":"Mantenere una tensione muscolare lieve e confortevole.","swimmingBenefits":["Aiuta a mantenere l’ampiezza di movimento necessaria alla nuotata e a ritrovare una sensazione di rilassamento."],"instructions":["In piedi vicino a una parete, afferra delicatamente una caviglia dietro di te.","Avvicina le ginocchia mantenendo il bacino neutro.","Respira senza tirare il piede e passa all’altro lato."],"commonMistakes":["Inarcare la schiena o tirare con forza il ginocchio."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata.","Cerca solo una tensione lieve: niente rimbalzi, spinte esterne o stretching doloroso."],"prerequisites":[],"easierVariation":"Usa la parete per l’equilibrio e fletti meno il ginocchio.","harderVariation":"Riduci l’appoggio solo se sei stabile.","defaultSets":1,"dose":{"mode":"time","durationSeconds":25,"sides":2,"positions":1,"secondsPerRep":3},"restSeconds":10,"equipment":["Corpo libero"],"youtubeSearchQuery":"Stretch dei quadricipiti in piedi esercizio tecnica","custom":false}'::jsonb),
('butterfly', null, '{"id":"butterfly","slug":"butterfly","name":"Butterfly Stretch","categories":["flessibilita"],"muscleGroups":["Adduttori","Anche"],"difficulty":"beginner","description":"Lascia scendere le ginocchia naturalmente, senza spingerle con le mani. Respira e inclina appena il busto dalle anche se confortevole.","objective":"Mantenere una tensione muscolare lieve e confortevole.","swimmingBenefits":["Aiuta a mantenere l’ampiezza di movimento necessaria alla nuotata e a ritrovare una sensazione di rilassamento."],"instructions":["Siediti con le piante dei piedi unite e la schiena lunga.","Lascia scendere le ginocchia naturalmente, senza spingerle con le mani.","Respira e inclina appena il busto dalle anche se confortevole."],"commonMistakes":["Premere sulle ginocchia o molleggiare."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata.","Cerca solo una tensione lieve: niente rimbalzi, spinte esterne o stretching doloroso."],"prerequisites":[],"easierVariation":"Allontana i piedi dal bacino.","harderVariation":"Inclina leggermente il bacino mantenendo la schiena lunga.","defaultSets":1,"dose":{"mode":"time","durationSeconds":25,"sides":1,"positions":1,"secondsPerRep":3},"restSeconds":10,"equipment":["Corpo libero"],"youtubeSearchQuery":"Butterfly Stretch esercizio tecnica","custom":false}'::jsonb),
('squat', null, '{"id":"squat","slug":"squat","name":"Bodyweight Squat","categories":["gambe"],"muscleGroups":["Quadricipiti","Glutei"],"difficulty":"beginner","description":"Porta il bacino indietro e piega le ginocchia seguendo le punte dei piedi. Spingi il pavimento e risali senza bloccare le ginocchia.","objective":"Allenare quadricipiti,glutei con un movimento controllato.","swimmingBenefits":["Allena la spinta e il controllo degli arti inferiori utili a partenze, virate e stabilità della nuotata."],"instructions":["Metti i piedi alla larghezza delle spalle e distribuisci il peso su tutta la pianta.","Porta il bacino indietro e piega le ginocchia seguendo le punte dei piedi.","Spingi il pavimento e risali senza bloccare le ginocchia."],"commonMistakes":["Far cedere le ginocchia all’interno o staccare i talloni."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Scendi meno e rallenta il gesto.","harderVariation":"Aggiungi una pausa di due secondi in basso.","defaultSets":3,"dose":{"mode":"reps","reps":12,"sides":1,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Bodyweight Squat esercizio tecnica","custom":false}'::jsonb),
('reverse-lunges', null, '{"id":"reverse-lunges","slug":"reverse-lunges","name":"Reverse Lunges","categories":["gambe"],"muscleGroups":["Quadricipiti","Glutei"],"difficulty":"intermediate","description":"Fai un passo indietro e piega entrambe le ginocchia senza toccare con forza il suolo. Spingi sul piede anteriore per tornare in piedi e completa entrambi i lati.","objective":"Allenare quadricipiti,glutei con un movimento controllato.","swimmingBenefits":["Allena la spinta e il controllo degli arti inferiori utili a partenze, virate e stabilità della nuotata."],"instructions":["In piedi, mantieni una base larga quanto le anche.","Fai un passo indietro e piega entrambe le ginocchia senza toccare con forza il suolo.","Spingi sul piede anteriore per tornare in piedi e completa entrambi i lati."],"commonMistakes":["Incrociare i piedi o spostare il ginocchio all’interno."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Riduci la discesa e tocca una parete per equilibrio.","harderVariation":"Scendi in tre secondi mantenendo il busto stabile.","defaultSets":3,"dose":{"mode":"reps","reps":10,"sides":2,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Reverse Lunges esercizio tecnica","custom":false}'::jsonb),
('single-glute-bridge', null, '{"id":"single-glute-bridge","slug":"single-glute-bridge","name":"Single Leg Glute Bridge","categories":["gambe"],"muscleGroups":["Glutei","Ischiocrurali"],"difficulty":"intermediate","description":"Spingi sul tallone a terra e solleva il bacino mantenendolo orizzontale. Scendi con controllo, senza cercare altezza dalla schiena, e cambia lato.","objective":"Allenare glutei,ischiocrurali con un movimento controllato.","swimmingBenefits":["Allena la spinta e il controllo degli arti inferiori utili a partenze, virate e stabilità della nuotata."],"instructions":["Sdraiati con un piede a terra vicino al bacino e l’altra gamba sollevata.","Spingi sul tallone a terra e solleva il bacino mantenendolo orizzontale.","Scendi con controllo, senza cercare altezza dalla schiena, e cambia lato."],"commonMistakes":["Ruotare il bacino o inarcare le lombari."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Usa entrambi i piedi a terra.","harderVariation":"Tieni due secondi nella posizione alta.","defaultSets":2,"dose":{"mode":"reps","reps":10,"sides":2,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Single Leg Glute Bridge esercizio tecnica","custom":false}'::jsonb),
('wall-sit', null, '{"id":"wall-sit","slug":"wall-sit","name":"Wall Sit","categories":["gambe"],"muscleGroups":["Quadricipiti","Glutei"],"difficulty":"beginner","description":"Scivola fino a un angolo confortevole delle ginocchia. Tieni i piedi ben appoggiati, respira e risali prima di perdere il controllo.","objective":"Allenare quadricipiti,glutei con un movimento controllato.","swimmingBenefits":["Allena la spinta e il controllo degli arti inferiori utili a partenze, virate e stabilità della nuotata."],"instructions":["Appoggia la schiena alla parete e porta i piedi un po’ avanti.","Scivola fino a un angolo confortevole delle ginocchia.","Tieni i piedi ben appoggiati, respira e risali prima di perdere il controllo."],"commonMistakes":["Scendere troppo o trattenere il respiro."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Mantieni il bacino più alto.","harderVariation":"Avvicinati a 90 gradi solo senza fastidio e con approvazione.","defaultSets":2,"dose":{"mode":"time","durationSeconds":35,"sides":1,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Parete"],"youtubeSearchQuery":"Wall Sit esercizio tecnica","custom":false}'::jsonb),
('calf-raises', null, '{"id":"calf-raises","slug":"calf-raises","name":"Calf Raises","categories":["gambe"],"muscleGroups":["Polpacci","Caviglie"],"difficulty":"beginner","description":"Sali lentamente sugli avampiedi senza far ruotare le caviglie. Scendi finché i talloni toccano il pavimento.","objective":"Allenare polpacci,caviglie con un movimento controllato.","swimmingBenefits":["Allena la spinta e il controllo degli arti inferiori utili a partenze, virate e stabilità della nuotata."],"instructions":["Stai in piedi vicino a una parete con piedi paralleli.","Sali lentamente sugli avampiedi senza far ruotare le caviglie.","Scendi finché i talloni toccano il pavimento."],"commonMistakes":["Rimbalzare o far cedere le caviglie verso l’esterno."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Usa entrambe le mani per equilibrio.","harderVariation":"Esegui una gamba alla volta con appoggio leggero.","defaultSets":3,"dose":{"mode":"reps","reps":20,"sides":1,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Calf Raises esercizio tecnica","custom":false}'::jsonb),
('split-squat', null, '{"id":"split-squat","slug":"split-squat","name":"Split Squat","categories":["gambe"],"muscleGroups":["Quadricipiti","Glutei"],"difficulty":"intermediate","description":"Scendi verticalmente piegando entrambe le ginocchia. Risali mantenendo il peso stabile e poi cambia gamba.","objective":"Allenare quadricipiti,glutei con un movimento controllato.","swimmingBenefits":["Allena la spinta e il controllo degli arti inferiori utili a partenze, virate e stabilità della nuotata."],"instructions":["Posiziona i piedi sfalsati su due binari, tallone posteriore sollevato.","Scendi verticalmente piegando entrambe le ginocchia.","Risali mantenendo il peso stabile e poi cambia gamba."],"commonMistakes":["Usare una base troppo stretta o spingere il ginocchio all’interno."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Riduci la profondità e usa la parete.","harderVariation":"Aggiungi una pausa in basso.","defaultSets":2,"dose":{"mode":"reps","reps":10,"sides":2,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Split Squat esercizio tecnica","custom":false}'::jsonb),
('single-rdl', null, '{"id":"single-rdl","slug":"single-rdl","name":"Single Leg Romanian Deadlift","categories":["gambe"],"muscleGroups":["Ischiocrurali","Glutei","Equilibrio"],"difficulty":"intermediate","description":"Inclina il busto dalle anche portando l’altra gamba indietro. Mantieni il bacino rivolto al pavimento e risali lentamente.","objective":"Allenare ischiocrurali,glutei,equilibrio con un movimento controllato.","swimmingBenefits":["Allena la spinta e il controllo degli arti inferiori utili a partenze, virate e stabilità della nuotata."],"instructions":["In piedi su una gamba, piega leggermente il ginocchio d’appoggio.","Inclina il busto dalle anche portando l’altra gamba indietro.","Mantieni il bacino rivolto al pavimento e risali lentamente."],"commonMistakes":["Aprire il bacino o arrotondare la schiena."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Tocca la parete o tieni la punta posteriore a terra.","harderVariation":"Allunga le braccia avanti mantenendo una piccola ampiezza.","defaultSets":2,"dose":{"mode":"reps","reps":8,"sides":2,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Single Leg Romanian Deadlift esercizio tecnica","custom":false}'::jsonb),
('tempo-squat', null, '{"id":"tempo-squat","slug":"tempo-squat","name":"Tempo Squat con discesa lenta","categories":["gambe"],"muscleGroups":["Quadricipiti","Glutei"],"difficulty":"intermediate","description":"Scendi contando tre secondi con ginocchia allineate alle punte. Risali in uno o due secondi senza perdere il controllo.","objective":"Allenare quadricipiti,glutei con un movimento controllato.","swimmingBenefits":["Allena la spinta e il controllo degli arti inferiori utili a partenze, virate e stabilità della nuotata."],"instructions":["Assumi la posizione dello squat, piedi stabili a terra.","Scendi contando tre secondi con ginocchia allineate alle punte.","Risali in uno o due secondi senza perdere il controllo."],"commonMistakes":["Accelerare in basso o cercare profondità eccessiva."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Riduci la profondità.","harderVariation":"Aggiungi un secondo di pausa alla fine della discesa.","defaultSets":2,"dose":{"mode":"reps","reps":10,"sides":1,"positions":1,"secondsPerRep":5},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Tempo Squat con discesa lenta esercizio tecnica","custom":false}'::jsonb),
('glute-bridge', null, '{"id":"glute-bridge","slug":"glute-bridge","name":"Glute Bridge","categories":["gambe"],"muscleGroups":["Glutei","Ischiocrurali"],"difficulty":"beginner","description":"Espira e solleva il bacino spingendo sui talloni. Ferma la salita quando spalle, anche e ginocchia sono allineate, poi scendi.","objective":"Allenare glutei,ischiocrurali con un movimento controllato.","swimmingBenefits":["Allena la spinta e il controllo degli arti inferiori utili a partenze, virate e stabilità della nuotata."],"instructions":["Sdraiati con ginocchia piegate, piedi a terra e braccia lungo i fianchi.","Espira e solleva il bacino spingendo sui talloni.","Ferma la salita quando spalle, anche e ginocchia sono allineate, poi scendi."],"commonMistakes":["Spingere dalla zona lombare o allargare troppo le ginocchia."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Solleva il bacino di pochi centimetri.","harderVariation":"Mantieni due secondi in alto.","defaultSets":3,"dose":{"mode":"reps","reps":15,"sides":1,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Glute Bridge esercizio tecnica","custom":false}'::jsonb),
('push-up', null, '{"id":"push-up","slug":"push-up","name":"Push-up","categories":["parte-superiore"],"muscleGroups":["Pettorali","Tricipiti","Spalle"],"difficulty":"intermediate","description":"Piega i gomiti orientandoli circa 30–45 gradi dal busto. Spingi il pavimento per risalire mantenendo il corpo unito.","objective":"Allenare pettorali,tricipiti,spalle con un movimento controllato.","swimmingBenefits":["Rinforza i muscoli di spinta e gli stabilizzatori scapolari per sostenere il controllo delle spalle in acqua."],"instructions":["Appoggia le mani poco oltre le spalle e allinea tronco e gambe.","Piega i gomiti orientandoli circa 30–45 gradi dal busto.","Spingi il pavimento per risalire mantenendo il corpo unito."],"commonMistakes":["Lasciar cedere il bacino o aprire i gomiti a 90 gradi."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Usa la parete o appoggia le ginocchia.","harderVariation":"Rallenta la discesa senza arrivare al cedimento.","defaultSets":3,"dose":{"mode":"reps","reps":10,"sides":1,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Push-up esercizio tecnica","custom":false}'::jsonb),
('wall-push-up', null, '{"id":"wall-push-up","slug":"wall-push-up","name":"Push-up al muro","categories":["parte-superiore"],"muscleGroups":["Pettorali","Tricipiti","Spalle"],"difficulty":"beginner","description":"Allontana i piedi quanto basta e piega i gomiti avvicinando il petto al muro. Spingi per tornare mantenendo tronco e gambe allineati.","objective":"Allenare pettorali,tricipiti,spalle con un movimento controllato.","swimmingBenefits":["Rinforza i muscoli di spinta e gli stabilizzatori scapolari per sostenere il controllo delle spalle in acqua."],"instructions":["Appoggia le mani alla parete all’altezza delle spalle.","Allontana i piedi quanto basta e piega i gomiti avvicinando il petto al muro.","Spingi per tornare mantenendo tronco e gambe allineati."],"commonMistakes":["Avvicinare solo la testa o curvare la schiena."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Avvicina i piedi alla parete.","harderVariation":"Allontana un poco i piedi dalla parete.","defaultSets":2,"dose":{"mode":"reps","reps":10,"sides":1,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Parete"],"youtubeSearchQuery":"Push-up al muro esercizio tecnica","custom":false}'::jsonb),
('pike-push-up', null, '{"id":"pike-push-up","slug":"pike-push-up","name":"Pike Push-up","categories":["parte-superiore"],"muscleGroups":["Spalle","Tricipiti"],"difficulty":"advanced","description":"Piega i gomiti lentamente avvicinando la testa al suolo davanti alle mani. Spingi e risali prima di perdere stabilità, senza appoggiare la testa.","objective":"Allenare spalle,tricipiti con un movimento controllato.","swimmingBenefits":["Rinforza i muscoli di spinta e gli stabilizzatori scapolari per sostenere il controllo delle spalle in acqua."],"instructions":["Da mani e piedi a terra solleva il bacino formando una V rovesciata.","Piega i gomiti lentamente avvicinando la testa al suolo davanti alle mani.","Spingi e risali prima di perdere stabilità, senza appoggiare la testa."],"commonMistakes":["Caricare il collo o scendere oltre il controllo disponibile."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":["Push-up e tenuta della posizione a V controllati; apprendimento con l’allenatore."],"easierVariation":"Sostituisci con push-up al muro.","harderVariation":"Rallenta la discesa con un’ampiezza controllata.","defaultSets":2,"dose":{"mode":"reps","reps":6,"sides":1,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Pike Push-up esercizio tecnica","custom":false}'::jsonb),
('prone-ytw', null, '{"id":"prone-ytw","slug":"prone-ytw","name":"Prone Y-T-W","categories":["parte-superiore"],"muscleGroups":["Scapole","Spalle","Dorsali"],"difficulty":"beginner","description":"Solleva appena le braccia in forma Y, poi T e poi W senza alzare il petto. Esegui le ripetizioni per ogni posizione e mantieni il collo rilassato.","objective":"Allenare scapole,spalle,dorsali con un movimento controllato.","swimmingBenefits":["Rinforza i muscoli di spinta e gli stabilizzatori scapolari per sostenere il controllo delle spalle in acqua."],"instructions":["Sdraiati a pancia in giù con fronte appoggiata su un asciugamano.","Solleva appena le braccia in forma Y, poi T e poi W senza alzare il petto.","Esegui le ripetizioni per ogni posizione e mantieni il collo rilassato."],"commonMistakes":["Inarcare la schiena o alzare le spalle verso le orecchie."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Muovi le braccia una posizione per volta senza sollevarle molto.","harderVariation":"Mantieni ogni sollevamento per due secondi.","defaultSets":2,"dose":{"mode":"reps","reps":6,"sides":1,"positions":3,"secondsPerRep":3},"restSeconds":30,"equipment":["Asciugamano"],"youtubeSearchQuery":"Prone Y-T-W esercizio tecnica","custom":false}'::jsonb),
('shoulder-taps', null, '{"id":"shoulder-taps","slug":"shoulder-taps","name":"Plank Shoulder Taps","categories":["parte-superiore","core"],"muscleGroups":["Addominali","Spalle","Scapole"],"difficulty":"intermediate","description":"Tocca una spalla con la mano opposta senza ruotare il bacino. Riappoggia la mano lentamente e alterna i lati.","objective":"Allenare addominali,spalle,scapole con un movimento controllato.","swimmingBenefits":["Rinforza i muscoli di spinta e gli stabilizzatori scapolari per sostenere il controllo delle spalle in acqua.","Allena il controllo del tronco e il trasferimento della forza mantenendo una posizione idrodinamica."],"instructions":["Assumi un plank sulle mani con piedi leggermente distanti.","Tocca una spalla con la mano opposta senza ruotare il bacino.","Riappoggia la mano lentamente e alterna i lati."],"commonMistakes":["Oscillare con il bacino o correre nei tocchi."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Appoggia le ginocchia e allarga la base.","harderVariation":"Avvicina poco i piedi mantenendo la stabilità.","defaultSets":2,"dose":{"mode":"reps","reps":10,"sides":2,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Plank Shoulder Taps esercizio tecnica","custom":false}'::jsonb),
('reverse-snow-angels', null, '{"id":"reverse-snow-angels","slug":"reverse-snow-angels","name":"Reverse Snow Angels","categories":["parte-superiore"],"muscleGroups":["Scapole","Dorsali","Spalle"],"difficulty":"beginner","description":"Solleva appena le mani e disegna un arco fino a dove le spalle consentono. Torna ai fianchi senza sollevare il petto.","objective":"Allenare scapole,dorsali,spalle con un movimento controllato.","swimmingBenefits":["Rinforza i muscoli di spinta e gli stabilizzatori scapolari per sostenere il controllo delle spalle in acqua."],"instructions":["Sdraiati a pancia in giù, fronte su un asciugamano e braccia lungo il corpo.","Solleva appena le mani e disegna un arco fino a dove le spalle consentono.","Torna ai fianchi senza sollevare il petto."],"commonMistakes":["Compensare con la schiena o irrigidire il collo."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Scorri le mani a terra e riduci l’arco.","harderVariation":"Mantieni una pausa a metà arco.","defaultSets":2,"dose":{"mode":"reps","reps":10,"sides":1,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Reverse Snow Angels esercizio tecnica","custom":false}'::jsonb),
('towel-row', null, '{"id":"towel-row","slug":"towel-row","name":"Rematore isometrico con asciugamano","categories":["parte-superiore"],"muscleGroups":["Scapole","Dorsali","Braccia"],"difficulty":"intermediate","description":"Tira delicatamente i gomiti indietro mentre i piedi oppongono una resistenza moderata, senza muoverti. Mantieni la schiena lunga, respira e rilascia gradualmente: non usare ancoraggi esterni.","objective":"Allenare scapole,dorsali,braccia con un movimento controllato.","swimmingBenefits":["Rinforza i muscoli di spinta e gli stabilizzatori scapolari per sostenere il controllo delle spalle in acqua."],"instructions":["Siediti con ginocchia piegate e passa un asciugamano integro sotto le piante dei piedi, tenendone le estremità.","Tira delicatamente i gomiti indietro mentre i piedi oppongono una resistenza moderata, senza muoverti.","Mantieni la schiena lunga, respira e rilascia gradualmente: non usare ancoraggi esterni."],"commonMistakes":["Strattonare, trattenere il respiro o tirare verso il viso."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata.","Nessun punto di ancoraggio. È un’attivazione isometrica auto-resistita: non equivale a un rematore con resistenza esterna. Evita asciugamani elastici o danneggiati."],"prerequisites":[],"easierVariation":"Riduci la tensione e la durata a dieci secondi.","harderVariation":"Aumenta poco la tensione solo con controllo dell’allenatore.","defaultSets":2,"dose":{"mode":"time","durationSeconds":20,"sides":1,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Asciugamano"],"youtubeSearchQuery":"Rematore isometrico con asciugamano esercizio tecnica","custom":false}'::jsonb),
('forearm-plank', null, '{"id":"forearm-plank","slug":"forearm-plank","name":"Forearm Plank","categories":["core"],"muscleGroups":["Addominali","Spalle"],"difficulty":"intermediate","description":"Allunga le gambe e allinea testa, bacino e talloni. Respira regolarmente e termina la tenuta appena perdi l’allineamento.","objective":"Allenare addominali,spalle con un movimento controllato.","swimmingBenefits":["Allena il controllo del tronco e il trasferimento della forza mantenendo una posizione idrodinamica."],"instructions":["Appoggia avambracci a terra con gomiti sotto le spalle.","Allunga le gambe e allinea testa, bacino e talloni.","Respira regolarmente e termina la tenuta appena perdi l’allineamento."],"commonMistakes":["Trattenere il respiro o lasciar scendere la zona lombare."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Appoggia le ginocchia.","harderVariation":"Allunga gradualmente la leva portando i gomiti poco avanti.","defaultSets":3,"dose":{"mode":"time","durationSeconds":35,"sides":1,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Forearm Plank esercizio tecnica","custom":false}'::jsonb),
('dead-bug', null, '{"id":"dead-bug","slug":"dead-bug","name":"Dead Bug","categories":["core"],"muscleGroups":["Addominali","Anche"],"difficulty":"beginner","description":"Espira e allunga lentamente un braccio e la gamba opposta. Torna al centro mantenendo il bacino stabile e alterna i lati.","objective":"Allenare addominali,anche con un movimento controllato.","swimmingBenefits":["Allena il controllo del tronco e il trasferimento della forza mantenendo una posizione idrodinamica."],"instructions":["Sdraiati con braccia al soffitto e anche e ginocchia a 90 gradi.","Espira e allunga lentamente un braccio e la gamba opposta.","Torna al centro mantenendo il bacino stabile e alterna i lati."],"commonMistakes":["Inarcare la schiena quando gli arti si allontanano."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Muovi solo i talloni verso il suolo.","harderVariation":"Allunga gli arti più vicino al pavimento senza perdere controllo.","defaultSets":3,"dose":{"mode":"reps","reps":10,"sides":2,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Dead Bug esercizio tecnica","custom":false}'::jsonb),
('side-plank', null, '{"id":"side-plank","slug":"side-plank","name":"Side Plank","categories":["core"],"muscleGroups":["Obliqui","Spalle","Glutei"],"difficulty":"intermediate","description":"Solleva il bacino mantenendo allineati spalla, anca e caviglie. Respira, scendi con controllo e cambia lato.","objective":"Allenare obliqui,spalle,glutei con un movimento controllato.","swimmingBenefits":["Allena il controllo del tronco e il trasferimento della forza mantenendo una posizione idrodinamica."],"instructions":["Sdraiati sul fianco con il gomito sotto la spalla.","Solleva il bacino mantenendo allineati spalla, anca e caviglie.","Respira, scendi con controllo e cambia lato."],"commonMistakes":["Collassare sulla spalla o ruotare il busto."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Piega le ginocchia e usale come appoggio.","harderVariation":"Allunga il braccio libero verso il soffitto.","defaultSets":2,"dose":{"mode":"time","durationSeconds":25,"sides":2,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Side Plank esercizio tecnica","custom":false}'::jsonb),
('bird-dog', null, '{"id":"bird-dog","slug":"bird-dog","name":"Bird Dog","categories":["core"],"muscleGroups":["Addominali","Glutei","Schiena"],"difficulty":"beginner","description":"Allunga lentamente un braccio e la gamba opposta senza ruotare il bacino. Ritorna al centro e completa entrambi i lati.","objective":"Allenare addominali,glutei,schiena con un movimento controllato.","swimmingBenefits":["Allena il controllo del tronco e il trasferimento della forza mantenendo una posizione idrodinamica."],"instructions":["Mettiti a quattro appoggi e guarda il pavimento.","Allunga lentamente un braccio e la gamba opposta senza ruotare il bacino.","Ritorna al centro e completa entrambi i lati."],"commonMistakes":["Sollevare troppo la gamba o inarcare la zona lombare."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Muovi solo una gamba o un braccio alla volta.","harderVariation":"Aggiungi una pausa di tre secondi in allungamento.","defaultSets":2,"dose":{"mode":"reps","reps":10,"sides":2,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Bird Dog esercizio tecnica","custom":false}'::jsonb),
('hollow-hold', null, '{"id":"hollow-hold","slug":"hollow-hold","name":"Hollow Body Hold","categories":["core","coordinazione"],"muscleGroups":["Addominali"],"difficulty":"intermediate","description":"Solleva appena le scapole e allunga gradualmente le gambe e le braccia. Mantieni soltanto la leva che ti permette di respirare senza inarcare la schiena.","objective":"Allenare addominali con un movimento controllato.","swimmingBenefits":["Allena il controllo del tronco e il trasferimento della forza mantenendo una posizione idrodinamica.","Allena equilibrio, percezione del corpo e coordinazione dei movimenti utili al controllo della nuotata."],"instructions":["Sdraiati e avvicina le ginocchia al petto mantenendo la zona lombare appoggiata.","Solleva appena le scapole e allunga gradualmente le gambe e le braccia.","Mantieni soltanto la leva che ti permette di respirare senza inarcare la schiena."],"commonMistakes":["Abbassare le gambe perdendo il contatto lombare con il suolo."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Tieni ginocchia piegate e braccia ai fianchi.","harderVariation":"Allunga le braccia sopra la testa senza perdere il controllo.","defaultSets":3,"dose":{"mode":"time","durationSeconds":20,"sides":1,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Hollow Body Hold esercizio tecnica","custom":false}'::jsonb),
('reverse-crunch', null, '{"id":"reverse-crunch","slug":"reverse-crunch","name":"Reverse Crunch","categories":["core"],"muscleGroups":["Addominali"],"difficulty":"beginner","description":"Espira e avvicina il bacino alle costole sollevandolo di pochi centimetri. Riappoggia lentamente il bacino senza lanciare le gambe.","objective":"Allenare addominali con un movimento controllato.","swimmingBenefits":["Allena il controllo del tronco e il trasferimento della forza mantenendo una posizione idrodinamica."],"instructions":["Sdraiati con anche e ginocchia flesse e braccia al suolo.","Espira e avvicina il bacino alle costole sollevandolo di pochi centimetri.","Riappoggia lentamente il bacino senza lanciare le gambe."],"commonMistakes":["Usare slancio o comprimere il collo."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Esegui soltanto una piccola retroversione del bacino.","harderVariation":"Rallenta la discesa in tre secondi.","defaultSets":2,"dose":{"mode":"reps","reps":12,"sides":1,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Reverse Crunch esercizio tecnica","custom":false}'::jsonb),
('bear-plank', null, '{"id":"bear-plank","slug":"bear-plank","name":"Bear Plank","categories":["core"],"muscleGroups":["Addominali","Spalle","Quadricipiti"],"difficulty":"intermediate","description":"Punta i piedi e solleva le ginocchia di pochi centimetri. Mantieni schiena neutra e respira senza alzare il bacino.","objective":"Allenare addominali,spalle,quadricipiti con un movimento controllato.","swimmingBenefits":["Allena il controllo del tronco e il trasferimento della forza mantenendo una posizione idrodinamica."],"instructions":["Da quattro appoggi, metti mani sotto le spalle e ginocchia sotto le anche.","Punta i piedi e solleva le ginocchia di pochi centimetri.","Mantieni schiena neutra e respira senza alzare il bacino."],"commonMistakes":["Sollevare troppo le ginocchia o irrigidire il collo."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Alterna brevi sollevamenti e appoggi.","harderVariation":"Tieni i piedi poco più vicini con il bacino fermo.","defaultSets":2,"dose":{"mode":"time","durationSeconds":25,"sides":1,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Bear Plank esercizio tecnica","custom":false}'::jsonb),
('squat-jump', null, '{"id":"squat-jump","slug":"squat-jump","name":"Squat Jump","categories":["esplosivita"],"muscleGroups":["Quadricipiti","Glutei","Polpacci"],"difficulty":"intermediate","description":"Fai un mezzo squat e salta verso l’alto con una spinta controllata. Atterra in modo silenzioso flettendo anche e ginocchia, allinea ginocchia e piedi e fermati prima del salto successivo.","objective":"Esprimere una spinta rapida con atterraggio controllato.","swimmingBenefits":["Sviluppa la capacità di esprimere forza rapidamente, una qualità utile per partenze e spinte dalle pareti."],"instructions":["Stai in piedi su una superficie piana, libera e non scivolosa.","Fai un mezzo squat e salta verso l’alto con una spinta controllata.","Atterra in modo silenzioso flettendo anche e ginocchia, allinea ginocchia e piedi e fermati prima del salto successivo."],"commonMistakes":["Atterrare rigido, far cedere le ginocchia o concatenare salti stanchi."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata.","Atterra in modo silenzioso flettendo anche e ginocchia, con ginocchia in linea con piedi e caviglie. Recupera almeno 60–90 secondi, anche di più se necessario. Non saltare fino al cedimento; fermati se peggiora la tecnica."],"prerequisites":["Approvazione dell’allenatore e riscaldamento completato.","Squat e atterraggio su due piedi controllati, senza dolore."],"easierVariation":"Squat con salita sugli avampiedi senza salto.","harderVariation":"Aumenta poco l’altezza solo conservando un atterraggio stabile.","defaultSets":3,"dose":{"mode":"reps","reps":5,"sides":1,"positions":1,"secondsPerRep":5},"restSeconds":75,"equipment":["Corpo libero"],"youtubeSearchQuery":"Squat Jump esercizio tecnica","custom":false}'::jsonb),
('broad-jump', null, '{"id":"broad-jump","slug":"broad-jump","name":"Broad Jump","categories":["esplosivita"],"muscleGroups":["Glutei","Quadricipiti","Polpacci"],"difficulty":"advanced","description":"Da un mezzo squat usa le braccia e salta in avanti per una distanza moderata. Atterra su entrambi i piedi flettendo anche e ginocchia, resta stabile due secondi e torna al punto di partenza camminando.","objective":"Esprimere una spinta rapida con atterraggio controllato.","swimmingBenefits":["Sviluppa la capacità di esprimere forza rapidamente, una qualità utile per partenze e spinte dalle pareti."],"instructions":["Verifica di avere spazio davanti e dietro, senza ostacoli.","Da un mezzo squat usa le braccia e salta in avanti per una distanza moderata.","Atterra su entrambi i piedi flettendo anche e ginocchia, resta stabile due secondi e torna al punto di partenza camminando."],"commonMistakes":["Cercare la massima distanza o perdere l’equilibrio all’arrivo."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata.","Atterra in modo silenzioso flettendo anche e ginocchia, con ginocchia in linea con piedi e caviglie. Recupera almeno 60–90 secondi, anche di più se necessario. Non saltare fino al cedimento; fermati se peggiora la tecnica."],"prerequisites":["Approvazione dell’allenatore e riscaldamento completato.","Squat e atterraggio su due piedi controllati, senza dolore.","Equilibrio monopodalico e salti di base stabili; apprendere il gesto con l’allenatore prima dell’uso autonomo."],"easierVariation":"Passo lungo avanti seguito da mezzo squat, senza salto.","harderVariation":"Aumenta di poco la distanza soltanto dopo atterraggi stabili.","defaultSets":3,"dose":{"mode":"reps","reps":4,"sides":1,"positions":1,"secondsPerRep":5},"restSeconds":75,"equipment":["Corpo libero"],"youtubeSearchQuery":"Broad Jump esercizio tecnica","custom":false}'::jsonb),
('skater-jumps', null, '{"id":"skater-jumps","slug":"skater-jumps","name":"Skater Jumps","categories":["esplosivita"],"muscleGroups":["Glutei","Quadricipiti","Caviglie"],"difficulty":"advanced","description":"Esegui un piccolo salto laterale sulla gamba opposta. Atterra con anca e ginocchio flessi e ginocchio allineato al piede, fermati prima di ripartire.","objective":"Esprimere una spinta rapida con atterraggio controllato.","swimmingBenefits":["Sviluppa la capacità di esprimere forza rapidamente, una qualità utile per partenze e spinte dalle pareti."],"instructions":["Parti su una gamba con il ginocchio leggermente flesso e spazio ai lati.","Esegui un piccolo salto laterale sulla gamba opposta.","Atterra con anca e ginocchio flessi e ginocchio allineato al piede, fermati prima di ripartire."],"commonMistakes":["Lasciare cadere il ginocchio all’interno o saltare troppo lontano."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata.","Atterra in modo silenzioso flettendo anche e ginocchia, con ginocchia in linea con piedi e caviglie. Recupera almeno 60–90 secondi, anche di più se necessario. Non saltare fino al cedimento; fermati se peggiora la tecnica."],"prerequisites":["Approvazione dell’allenatore e riscaldamento completato.","Squat e atterraggio su due piedi controllati, senza dolore.","Equilibrio monopodalico e salti di base stabili; apprendere il gesto con l’allenatore prima dell’uso autonomo."],"easierVariation":"Fai passi laterali senza staccare entrambi i piedi.","harderVariation":"Allunga moderatamente il salto senza perdere equilibrio.","defaultSets":2,"dose":{"mode":"reps","reps":5,"sides":2,"positions":1,"secondsPerRep":5},"restSeconds":75,"equipment":["Corpo libero"],"youtubeSearchQuery":"Skater Jumps esercizio tecnica","custom":false}'::jsonb),
