('pause-squat-jump', null, '{"id":"pause-squat-jump","slug":"pause-squat-jump","name":"Squat Jump con pausa","categories":["esplosivita"],"muscleGroups":["Quadricipiti","Glutei"],"difficulty":"advanced","description":"Mantieni due secondi di pausa e salta verticalmente senza rimbalzo preparatorio. Atterra ammortizzando con anche e ginocchia allineate ai piedi e resetta la posizione.","objective":"Esprimere una spinta rapida con atterraggio controllato.","swimmingBenefits":["Sviluppa la capacità di esprimere forza rapidamente, una qualità utile per partenze e spinte dalle pareti."],"instructions":["Assumi un mezzo squat stabile su superficie non scivolosa.","Mantieni due secondi di pausa e salta verticalmente senza rimbalzo preparatorio.","Atterra ammortizzando con anche e ginocchia allineate ai piedi e resetta la posizione."],"commonMistakes":["Rimbalzare prima della spinta o cedere con le ginocchia all’arrivo."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata.","Atterra in modo silenzioso flettendo anche e ginocchia, con ginocchia in linea con piedi e caviglie. Recupera almeno 60–90 secondi, anche di più se necessario. Non saltare fino al cedimento; fermati se peggiora la tecnica."],"prerequisites":["Approvazione dell’allenatore e riscaldamento completato.","Squat e atterraggio su due piedi controllati, senza dolore.","Equilibrio monopodalico e salti di base stabili; apprendere il gesto con l’allenatore prima dell’uso autonomo."],"easierVariation":"Pausa in mezzo squat seguita da risalita senza salto.","harderVariation":"Mantieni una pausa di tre secondi prima della spinta.","defaultSets":2,"dose":{"mode":"reps","reps":5,"sides":1,"positions":1,"secondsPerRep":5},"restSeconds":75,"equipment":["Corpo libero"],"youtubeSearchQuery":"Squat Jump con pausa esercizio tecnica","custom":false}'::jsonb),
('single-balance', null, '{"id":"single-balance","slug":"single-balance","name":"Single Leg Balance","categories":["coordinazione"],"muscleGroups":["Equilibrio","Caviglie","Glutei"],"difficulty":"beginner","description":"Solleva un piede e mantieni il ginocchio d’appoggio morbido. Fissa un punto davanti e mantieni il bacino orizzontale, poi cambia lato.","objective":"Allenare equilibrio,caviglie,glutei con un movimento controllato.","swimmingBenefits":["Allena equilibrio, percezione del corpo e coordinazione dei movimenti utili al controllo della nuotata."],"instructions":["Stai vicino a una parete su una superficie stabile e libera.","Solleva un piede e mantieni il ginocchio d’appoggio morbido.","Fissa un punto davanti e mantieni il bacino orizzontale, poi cambia lato."],"commonMistakes":["Bloccare il ginocchio o aggrapparsi con le dita del piede."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Tocca la parete con un dito.","harderVariation":"Muovi lentamente le braccia, mantenendo gli occhi aperti.","defaultSets":1,"dose":{"mode":"time","durationSeconds":30,"sides":2,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Single Leg Balance esercizio tecnica","custom":false}'::jsonb),
('single-reach', null, '{"id":"single-reach","slug":"single-reach","name":"Single Leg Reach","categories":["coordinazione"],"muscleGroups":["Equilibrio","Glutei","Anche"],"difficulty":"intermediate","description":"Inclina il busto dalle anche e raggiungi un punto davanti con la mano. Torna in piedi controllando il bacino e cambia lato dopo le ripetizioni.","objective":"Allenare equilibrio,glutei,anche con un movimento controllato.","swimmingBenefits":["Allena equilibrio, percezione del corpo e coordinazione dei movimenti utili al controllo della nuotata."],"instructions":["Stai su una gamba vicino a una parete, con ginocchio morbido.","Inclina il busto dalle anche e raggiungi un punto davanti con la mano.","Torna in piedi controllando il bacino e cambia lato dopo le ripetizioni."],"commonMistakes":["Ruotare il ginocchio all’interno o cercare un punto troppo lontano."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Tocca il suolo con la punta del piede libero.","harderVariation":"Raggiungi punti in direzioni diverse con ampiezza contenuta.","defaultSets":1,"dose":{"mode":"reps","reps":8,"sides":2,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Single Leg Reach esercizio tecnica","custom":false}'::jsonb),
('bear-crawl', null, '{"id":"bear-crawl","slug":"bear-crawl","name":"Bear Crawl","categories":["coordinazione"],"muscleGroups":["Addominali","Spalle","Coordinazione"],"difficulty":"intermediate","description":"Avanza lentamente con mano e piede opposti per piccoli passi. Mantieni il bacino basso e fermati prima di ostacoli, poi torna indietro con controllo.","objective":"Allenare addominali,spalle,coordinazione con un movimento controllato.","swimmingBenefits":["Allena equilibrio, percezione del corpo e coordinazione dei movimenti utili al controllo della nuotata."],"instructions":["Da quattro appoggi solleva le ginocchia di pochi centimetri.","Avanza lentamente con mano e piede opposti per piccoli passi.","Mantieni il bacino basso e fermati prima di ostacoli, poi torna indietro con controllo."],"commonMistakes":["Fare passi grandi o oscillare con il bacino."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Resta nel bear plank o cammina con ginocchia a terra.","harderVariation":"Aggiungi pochi passi indietro senza accelerare.","defaultSets":1,"dose":{"mode":"time","durationSeconds":20,"sides":1,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Bear Crawl esercizio tecnica","custom":false}'::jsonb),
('cross-crawl', null, '{"id":"cross-crawl","slug":"cross-crawl","name":"Cross Crawl in piedi","categories":["coordinazione"],"muscleGroups":["Coordinazione","Addominali","Anche"],"difficulty":"beginner","description":"Solleva un ginocchio e avvicina la mano o il gomito opposto senza forzare. Alterna i lati a ritmo tranquillo respirando regolarmente.","objective":"Allenare coordinazione,addominali,anche con un movimento controllato.","swimmingBenefits":["Allena equilibrio, percezione del corpo e coordinazione dei movimenti utili al controllo della nuotata."],"instructions":["In piedi con base stabile, allunga la colonna e rilassa le spalle.","Solleva un ginocchio e avvicina la mano o il gomito opposto senza forzare.","Alterna i lati a ritmo tranquillo respirando regolarmente."],"commonMistakes":["Curvare il collo o accelerare perdendo equilibrio."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Solleva meno il ginocchio e toccalo con la mano.","harderVariation":"Inserisci una pausa in equilibrio a ogni sollevamento.","defaultSets":1,"dose":{"mode":"time","durationSeconds":30,"sides":1,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Cross Crawl in piedi esercizio tecnica","custom":false}'::jsonb),
('streamline', null, '{"id":"streamline","slug":"streamline","name":"Streamline Hold in piedi","categories":["coordinazione"],"muscleGroups":["Spalle","Addominali","Scapole"],"difficulty":"beginner","description":"Porta le braccia sopra la testa e sovrapponi le mani entro l’ampiezza indolore. Allungati verso l’alto senza inarcare la schiena né stringere il collo.","objective":"Allenare spalle,addominali,scapole con un movimento controllato.","swimmingBenefits":["Allena equilibrio, percezione del corpo e coordinazione dei movimenti utili al controllo della nuotata."],"instructions":["Stai in piedi con piedi stabili, bacino neutro e costole rilassate.","Porta le braccia sopra la testa e sovrapponi le mani entro l’ampiezza indolore.","Allungati verso l’alto senza inarcare la schiena né stringere il collo."],"commonMistakes":["Aprire le costole o forzare le spalle dietro la testa."],"safetyNotes":["Interrompi se senti dolore, capogiri o fastidio articolare. Respira e conserva sempre una tecnica controllata."],"prerequisites":[],"easierVariation":"Tieni le braccia leggermente avanti o separate.","harderVariation":"Sali poco sugli avampiedi mantenendo l’allineamento.","defaultSets":3,"dose":{"mode":"time","durationSeconds":20,"sides":1,"positions":1,"secondsPerRep":3},"restSeconds":30,"equipment":["Corpo libero"],"youtubeSearchQuery":"Streamline Hold in piedi esercizio tecnica","custom":false}'::jsonb)
